int main() {
    int N;
    string T;
    cin >> N >> T;

    long long M = 1;
    for (int i = 0; i < N; i++) M *= 3;

    // swap digits 1<->2 in base 3
    auto swapDigits = [&](long long x) -> long long {
        long long result = 0, base = 1;
        for (int i = 0; i < N; i++) {
            int d = x % 3;
            if (d == 1) d = 2;
            else if (d == 2) d = 1;
            result += d * base;
            x /= 3;
            base *= 3;
        }
        return result;
    };

    // pos[p] = current position of person p
    vector<long long> pos(M);
    iota(pos.begin(), pos.end(), 0LL);

    for (char c : T) {
        if (c == 'R') {
            for (long long p = 0; p < M; p++)
                pos[p] = (pos[p] + 1) % M;
        } else {
            for (long long p = 0; p < M; p++)
                pos[p] = swapDigits(pos[p]);
        }
    }

    for (long long p = 0; p < M; p++)
        cout << pos[p] << "\n";

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

using int64 = long long;

// We represent a position x (0 <= x < 3^N) as
// x = sum d_k * 3^k.
// Salsa transforms each ternary digit by swapping 1 <-> 2, i.e.
// d -> 0 if d=0, 3-d otherwise.
// This is exactly: S(x) = M - x, where M = 3^N - 1.
//
// Rumba is: R(x) = x + 1 (mod 3^N).
//
// Any composition of these two operations is always of the form:
//   x -> a*x + b (mod 3^N), where a is either +1 or -1.
// Start with identity: a=1, b=0.
// Applying R after current map gives:
//   x -> (a*x + b) + 1 = a*x + (b+1)
// Applying S after current map gives:
//   x -> M - (a*x + b) = (-a)*x + (M-b)
//
// After processing all songs, for each original position i,
// final position is (a*i + b) mod 3^N.

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    string T;
    cin >> N >> T;

    int64 mod = 1;
    for (int i = 0; i < N; ++i) mod *= 3;

    int64 M = mod - 1;
    int64 a = 1; // either 1 or -1 modulo mod conceptually
    int64 b = 0;

    for (char c : T) {
        if (c == 'R') {
            b++;
            if (b >= mod) b -= mod;
        } else { // 'S'
            a = -a;
            b = M - b;
            if (b < 0) b += mod;
        }
    }

    for (int64 i = 0; i < mod; ++i) {
        int64 ans;
        if (a == 1) ans = (i + b) % mod;
        else {
            ans = (b - i) % mod;
            if (ans < 0) ans += mod;
        }
        cout << ans << '\n';
    }

    return 0;
}

import java.util.Scanner;

public class Dance {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int N = sc.nextInt();
        String T = sc.next();
        sc.close();

        int total = (int) Math.pow(3, N);
        int[] pos = new int[total];
        for (int i = 0; i < total; i++) {
            pos[i] = i;
        }

        for (char c : T.toCharArray()) {
            if (c == 'S') {
                for (int i = 0; i < total; i++) {
                    pos[i] = salsa(pos[i], N);
                }
            } else { // 'R'
                for (int i = 0; i < total; i++) {
                    pos[i] = (pos[i] + 1) % total;
                }
            }
        }

        // Output final positions for positions 0..total-1
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < total; i++) {
            if (i > 0) sb.append(" ");
            sb.append(pos[i]);
        }
        System.out.println(sb.toString());
    }

    static int salsa(int x, int N) {
        int result = 0;
        int pow = 1;
        for (int i = 0; i < N; i++) {
            int digit = x % 3;
            if (digit == 1) digit = 2;
            else if (digit == 2) digit = 1;
            result += digit * pow;
            pow *= 3;
            x /= 3;
        }
        return result;
    }
}

