public class Main {
    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String T = br.readLine();
        if (T == null) T = "";
        T = T.trim();

        long add = 0;          // accumulated rumba shift
        long pow3 = 1;         // 3^k after processing k salsa operations

        for (int idx = T.length() - 1; idx >= 0; idx--) {
            char c = T.charAt(idx);
            if (c == 'R') {
                add += 1;
            } else if (c == 'S') {
                // Salsa transforms x -> f(x), where in balanced form:
                // f(x) = 2 * (3^N - 1)/2 - x = (3^N - 1) - x
                // When composing from right to left on affine form over base-3 digits,
                // the current accumulated constant transforms as:
                // add -> f(add) = (3^k - 1) - add, where k is number of S seen so far.
                add = (pow3 - 1) - add;
                pow3 *= 3;
            }
        }

        // After all songs, final mapping is:
        // pos -> sign * pos + add   over modulus 3^N,
        // where sign = (-1)^(#S). Since after processing all chars, pow3 = 3^N.
        long mod = pow3;
        boolean oddS = false;
        for (int i = 0; i < T.length(); i++) {
            if (T.charAt(i) == 'S') oddS = !oddS;
        }

        StringBuilder sb = new StringBuilder();
        for (long i = 0; i < mod; i++) {
            long ans;
            if (oddS) {
                ans = add - i;
            } else {
                ans = add + i;
            }
            ans %= mod;
            if (ans < 0) ans += mod;
            if (i > 0) sb.append('\n');
            sb.append(ans);
        }

        System.out.print(sb.toString());
    }
}

