int swap12(int x, int N) {
    int result = 0, base = 1;
    for (int i = 0; i < N; i++) {
        int d = x % 3; x /= 3;
        if (d == 1) d = 2; else if (d == 2) d = 1;
        result += d * base; base *= 3;
    }
    return result;
}

