#include <stdlib.h>

int main() {
    int N;
    scanf("%d", &N);
    char T[200001];
    scanf("%s", T);
    int len = strlen(T);

    int M = 1;
    for (int i = 0; i < N; i++) M *= 3;

    int *salsa = malloc(M * sizeof(int));
    // Precompute salsa
    for (int i = 0; i < M; i++) {
        int x = i;
        int res = 0;
        int pow3 = 1;
        for (int d = 0; d < N; d++) {
            int digit = x % 3;
            if (digit == 1) digit = 2;
            else if (digit == 2) digit = 1;
            res += digit * pow3;
            pow3 *= 3;
            x /= 3;
        }
        salsa[i] = res;
    }

    int shift = 0;
    int flip = 0; // 0 = identity, 1 = salsa applied

    for (int i = len - 1; i >= 0; i--) {
        if (T[i] == 'R') {
            shift = (shift + 1) % M;
        } else { // 'S'
            flip = 1 - flip;
        }
    }

    int *ans = malloc(M * sizeof(int));
    for (int i = 0; i < M; i++) {
        int pos;
        if (flip == 0) {
            pos = (i + shift) % M;
        } else {
            pos = (salsa[i] + shift) % M;
        }
        ans[pos] = i; // person i ends at pos
    }

    for (int i = 0; i < M; i++) {
        printf("%d\n", ans[i]);
    }

    free(salsa);
    free(ans);
    return 0;
}

#include <stdio.h>
