#include <string.h>

typedef long long ll;

static ll pow3_int(int n) {
    ll r = 1;
    while (n--) r *= 3;
    return r;
}

int main(void) {
    int N;
    char T[1000005];

    if (scanf("%d", &N) != 1) return 0;
    if (scanf("%s", T) != 1) return 0;

    ll M = pow3_int(N);          // number of positions: 3^N
    ll a = 1 % M;                // current transformation: f(x) = a*x + b + c(x)
    ll b = 0;                    // where c(x) = digitwise swap 1<->2 in base 3
                                 // and c(c(x)) = x, c(x+y)=c(x)+c(y) mod 3^N

    for (int i = 0; T[i]; i++) {
        if (T[i] == 'R') {
            // R after current map: x -> f(x)+1
            b = (b + 1) % M;
        } else { // 'S'
            // S after current map: x -> c(f(x))
            // Since f(x) is always of form a*x + b or a*c(x)+b with a in {1,-1},
            // and c is affine over ternary digits: c(y) = (M-1) - y = -1 - y (mod M)
            // the closure gives:
            // if current is x -> a*x + b, then after S: x -> (-a)*c(x) + ((M-1)-b)
            // if current is x -> a*c(x) + b, then after S: x -> (-a)*x + ((M-1)-b)
            //
            // We can encode both cases by letting a be either +1 or -1 and toggling
            // whether c is applied using sign parity. Simpler: represent current map as:
            // f(x) = x + b        if a = 1
            // f(x) = c(x) + b     if a = -1
            //
            // Under S:
            // S(x+b)   = c(x+b)   = c(x)+c(b)
            // S(c(x)+b)= c(c(x)+b)= x+c(b)
            //
            // Since c(b) = (M-1)-b mod M, just toggle a and replace b by c(b).
            a = -a;
            b = (M - 1 - b) % M;
        }
    }

    // Output final position of each original person 0..M-1
    // If a=1, f(x)=x+b mod M
    // If a=-1, f(x)=c(x)+b = (M-1-x)+b mod M
    for (ll x = 0; x < M; x++) {
        ll y;
        if (a == 1) y = (x + b) % M;
        else y = ((M - 1 - x) + b) % M;

        if (x) putchar(' ');
        printf("%lld", y);
    }
    putchar('\n');

    return 0;
}
